solution:
function repeat(n, fn) {
  for (let i = 0; i < n; i++) fn()
}

function once(fn) {
  let called = false
  return function(...args) {
    if (!called) {
      called = true
      return fn(...args)
    }
  }
}

repeat(3, () => console.log("Hello!"))
const greet = once((name) => console.log("Hi " + name))
greet("Riya")
greet("Priya")
